		if _, named := os.LookupEnv("LLM_DENSE_BANK"); !named {
			if err := os.Setenv("LLM_DENSE_BANK", llm.ShippedDenseBank); err != nil {
				log.Fatalf("setting the shipped dense bank: %v", err)
			}
		}
		log.Printf("llm: dense bank %s", llm.DenseBankPlan())
