			if err := os.Setenv("LLM_MOE_BANK", llm.ShippedMoEBank); err != nil {
				log.Fatalf("setting the shipped MoE bank: %v", err)
			}
		}
		log.Printf("llm: moe bank %s", llm.MoEBankPlanFromEnv())
