// TestGPUAlbertScaling is the measurement R1 asked for: PL-BERT costs 4 ms at
// fifty tokens and 75 at three hundred and twenty-one, which is 18.8x the
// time for 6.4x the work, and a layer's cost per token has to say which
// dispatch owns the difference.
//
// It is not a correctness test and asserts nothing about time -- a bound on a
// duration would fail on a busy machine and tell nobody anything. What it
// asserts is the *shape*: attention's cost per token must grow with the
// sequence, because its dispatch is one workgroup per (head, query) and each
// one walks every key, while every projection's must not, because a GEMM over
// T rows is T times the same work. If that ever stops being true the kernel
// underneath has changed and this is the test that noticed.
func TestGPUAlbertScaling(t *testing.T) {
	dev, done := newTestDevice(t)
	defer done()
	model := loadModel(t)
	g, err := NewGPUAlbert(dev, model.BERT, model.BERT.Config.MaxPositionEmbed)
	if err != nil {
		t.Fatal(err)
	}
	defer g.Destroy()

	// 50 is the reference utterance, 321 is R1's paragraph, 510 is the
	// model's own ceiling: the voice packs have 510 style rows, so an
	// utterance cannot have more phonemes than that.
	lengths := []int{50, 100, 200, 321, 410, 510}
	// One row per dispatch kind, in the order the graph records them, and
	// two derived rows: the whole layer and the whole encoder.
	perKind := map[string][]float64{}
	var kinds []string
	layer := make([]float64, len(lengths))
	attn := make([]float64, len(lengths))

	for i, n := range lengths {
		stages, err := g.Profile(n)
		if err != nil {
			t.Fatal(err)
		}
		for _, s := range stages {
			if _, seen := perKind[s.Kind]; !seen {
				kinds = append(kinds, s.Kind)
				perKind[s.Kind] = make([]float64, len(lengths))
			}
			perKind[s.Kind][i] += s.Time * 1000
			layer[i] += s.Time * 1000
			if s.Kind == "attention" {
				attn[i] += s.Time * 1000
			}
		}
	}

	head := "%-14s"
	args := []any{"us a layer"}
	for _, n := range lengths {
		head += " %8d"
		args = append(args, n)
	}
	t.Logf(head, args...)
	for _, k := range kinds {
		line, a := "%-14s", []any{k}
		for i := range lengths {
			line += " %8.0f"
			a = append(a, perKind[k][i]*1000)
		}
		t.Logf(line, a...)
	}
	for _, row := range []struct {
		name  string
		vals  []float64
		scale float64
	}{
		{"layer, us", layer, 1000},
		{"12 layers, ms", layer, float64(g.cfg.NumHiddenLayers)},
	} {
		line, a := "%-14s", []any{row.name}
		for i := range lengths {
			line += " %8.1f"
			a = append(a, row.vals[i]*row.scale)
		}
		t.Logf(line, a...)
	}
	// Per token, which is the number that says linear from not.
	for _, row := range []struct {
		name string
		vals []float64
	}{
		{"attn, us/tok", attn},
		{"layer, us/tok", layer},
	} {
		line, a := "%-14s", []any{row.name}
		for i := range lengths {
			line += " %8.2f"
			a = append(a, row.vals[i]*1000/float64(lengths[i]))
		}
		t.Logf(line, a...)
	}

