	// attention per token at the reference length: one workgroup per query
	// walking every key is linear per token, so this ratio should track the
	// sequence ratio rather than sit at one.
	first, last := attn[0]/float64(lengths[0]), attn[len(attn)-1]/float64(lengths[len(lengths)-1])
	if last <= 1.5*first {
		t.Errorf("attention is %.2f us/token at %d and %.2f at %d: "+
			"it is no longer superlinear in the sequence, so this test is measuring a different kernel",
			first*1000, lengths[0], last*1000, lengths[len(lengths)-1])
	}
